    def intersect(p1: Tuple[float, float], q1: Tuple[float, float], p2: Tuple[float, float], q2: Tuple[float, float]) -> bool:
        if ccw(p1, q1, p2) != ccw(p1, q1, q2) and ccw(p2, q2, p1) != ccw(p2, q2, q1):
            return True
        if on_segment(p1, q1, p2): return True
        if on_segment(p1, q1, q2): return True
        if on_segment(p2, q2, p1): return True
