    return ((x2 - x1) ** 2 + (y2 - y1) ** 2) ** 0.5

def slope(x1, y1, x2, y2):
    if x2 == x1:
        return float('inf')
    return (y2 - y1) / (x2 - x1)

def intercept(x, y, m):
    return y - m * x

def point_on_line(x, y, x1, y1, x2, y2):
    d = distance(x1, y1, x2, y2)
    d1 = distance(x, y, x1, y1)
    d2 = distance(x, y, x2, y2)
    return abs(d1 + d2 - d) < 1e-9

def max_fruits(n, fruits):
